#include <iostream>
#include <queue>
#include <map>
using namespace std;
typedef map<int,int> mi;

mi graph[7000];
char grid[20][20];
int size_n, size_m, total_nodes, parent[7000], flow_value[7000], target_map[10][10];

int max_flow(int start, int end, int capacity){
  int total=0;
  for (int f=1; f--;){
    for (int i=total_nodes; i--;) parent[i]=-1;
    parent[start]=start;
    flow_value[start]=capacity;
    queue<int> q;
    q.push(start);
    while (!q.empty()){
      int node=q.front(); q.pop();
      if (node==end){
        for (int cur=node; cur!=start; cur=parent[cur]){
          graph[parent[cur]][cur]-=flow_value[end];
          graph[cur][parent[cur]]+=flow_value[end];
        }
        total+=flow_value[end];
        break;
      }
      for (auto it=graph[node].begin(); it!=graph[node].end(); it++){
        if (it->second>=capacity && parent[it->first]==-1){
          parent[it->first]=node;
          flow_value[it->first]=min(it->second,flow_value[node]);
          q.push(it->first);
        }
      }
    }
  }
  return total;
}

int encode_node(int x,int y,int t){
  return x+y*size_n+t*size_n*size_n+2;
}

int main(){
  ios::sync_with_stdio(false);
  cin>>size_n>>size_m;

  int total_res=0;
  for (int i=0; i<size_n; i++){
    for (int j=0; j<size_n; j++){
      cin>>grid[i][j];
      if (grid[i][j]>'0' && grid[i][j]<='9') graph[0][encode_node(i,j,0)]=grid[i][j]-'0';
    }
  }
  for (int i=0; i<size_n; i++) cin>>grid[i];

  static const int dx[]={-1,0,1,0};
  static const int dy[]={0,-1,0,1};

  queue<pair<int,int>> q_bfs;
  for (int i=size_n-1; i>=0; i--){
    for (int j=size_n-1; j>=0; j--){
      if (grid[i][j]=='Z') target_map[i][j]=0, q_bfs.emplace(i,j);
      else target_map[i][j]=m+1;
    }
  }

  while (!q_bfs.empty()){
    auto p=q_bfs.front(); q_bfs.pop();
    int i=p.first, j=p.second;
    for (int dir=0; dir<4; dir++){
      int t=target_map[i][j];
      int x=i+dx[dir], y=j+dy[dir];
      if (x>=0 && y>=0 && x<size_n && y<size_n && grid[x][y]!='Y' && t+1<target_map[x][y]){
        target_map[x][y]=t+1;
        q_bfs.emplace(x,y);
      }
    }
  }

  total_nodes=encode_node(size_n-1,size_n-1,m)+1;

  for (int i=0; i<size_n; i++){
    for (int j=0; j<size_n; j++){
      for (int t=0; t<m; t++){
        if (t<m) for (int q=0; q<4; q++){
          int x=i+dx[q], y=j+dy[q];
          if (x>=0 && y>=0 && x<size_n && y<size_n && grid[x][y]!='Y' && t+1<target_map[x][y]+(grid[x][y]>'0' && grid[x][y]<='9') && t<target_map[i][j]){
            graph[encode_node(i,j,t)][encode_node(x,y,t+1)]=1000;
          }
        }
        if (grid[i][j]>'0' && grid[i][j]<='9'){
          graph[encode_node(i,j,t)][encode_node(i,j,m)]=grid[i][j]-'0';
        }
      }
      if (grid[i][j]>'0' && grid[i][j]<='9'){
        graph[encode_node(i,j,m)][1]=grid[i][j]-'0';
      }
    }
  }

  for (int u=8; u; u/=2) total_res+=max_flow(0,1,u);
  cout<<total_res<<'\n';
}
